function evaluate(input, helpers) {
  var a = input.action || {};
  var cmd = (a.paramsSummary && typeof a.paramsSummary.command === 'string') ? a.paramsSummary.command : '';
  var isSubmission = a.canonicalKind === 'execute' && /(^|[;&|(\s])git\s+(commit|push)\b/.test(cmd);
  if (!isSubmission) {
    return { decision: 'allow', matched: false, reason: '不在设计门禁范围内（非 git 提交/推送动作），放行' };
  }
  var facts = (input.context && input.context.facts) ? input.context.facts : {};
  var gate = facts.designGate;
  var resolution = (gate && typeof gate.resolution === 'string') ? gate.resolution : 'unknown';
  if (resolution === 'approved' || resolution === 'not_required') {
    return { decision: 'allow', matched: true, reason: '设计门禁事实为 ' + resolution + '，允许提交' };
  }
  return { decision: 'block', matched: true, reason: '非简单高成本变更缺少 Owner 设计批准（designGate resolution=' + resolution + '，未知/未批准均不视为已批准），阻止 git 提交；方向授权或测试通过不能替代设计批准' };
}
